import org.junit.jupiter.params.provider.EnumSource;

class RdfParserOptimizationIntegrationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String P = "PREFIX parse: <http://rdf4j.org/function/parse#>\n"
			+ "PREFIX ex: <urn:ex:>\nPREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>\n";
	private static final String DATA = "<urn:ex:alice> <urn:ex:name> \"Alice\"; <urn:ex:age> 32 .";
	private static final String CONFIG = "[] parse:content ?doc; parse:format \"text/turtle\" . ";

	enum Backend {
		MEMORY,
		NATIVE,
		LMDB
	}

	@TempDir
	Path directory;
	private SailRepository repository;
	private RepositoryConnection connection;

	private void open(Backend backend) {
		Sail base = switch (backend) {
		case MEMORY -> new MemoryStore();
		case NATIVE -> new NativeStore(directory.toFile());
		case LMDB -> new LmdbStore(directory.toFile());
		};
		repository = new SailRepository(new RdfParserSail(base));
		repository.init();
		connection = repository.getConnection();
	}

	@AfterEach
	void close() {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
		}
	}

	private List<BindingSet> select(String sparql, String document) {
		var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, P + sparql);
		if (document != null) {
			query.setBinding("doc", VF.createLiteral(document));
		}
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private void update(String sparql, String document) {
		var update = connection.prepareUpdate(QueryLanguage.SPARQL, P + sparql);
		update.setBinding("doc", VF.createLiteral(document));
		update.execute();
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void chainedCallsCanAppearBeforeTheirProviders(Backend backend) {
		open(backend);
		var rows = select("SELECT ?s ?o WHERE { ?next parse:turtle (?s <urn:p> ?o) . "
				+ "?doc parse:turtle (?source <urn:next> ?next) }",
				"<urn:source> <urn:next> \"<urn:s> <urn:p> <urn:o> .\" .");
		assertEquals(1, rows.size());
		assertEquals(VF.createIRI("urn:s"), rows.get(0).getValue("s"));
		assertEquals(VF.createIRI("urn:o"), rows.get(0).getValue("o"));
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void chainedCallsRetainPreboundOutputConstraints(Backend backend) {
		open(backend);
		String document = "<urn:source> <urn:next> \"<urn:s> <urn:p> <urn:o> .\" .";
		var query = connection.prepareTupleQuery(P + "SELECT ?s ?o WHERE { "
				+ "?next parse:turtle (?s <urn:p> ?o) . ?doc parse:turtle (?source <urn:next> ?next) }");
		query.setBinding("doc", VF.createLiteral(document));
		query.setBinding("next", VF.createLiteral("<urn:s> <urn:p> <urn:o> ."));
		try (var rows = query.evaluate()) {
			assertTrue(rows.hasNext());
			assertEquals(VF.createIRI("urn:s"), rows.next().getValue("s"));
			assertFalse(rows.hasNext());
		}
		query.setBinding("next", VF.createLiteral("<urn:other> <urn:p> <urn:o> ."));
		try (var rows = query.evaluate()) {
			assertFalse(rows.hasNext());
		}
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void tupleAndServiceCallsCanFeedEachOther(Backend backend) {
		open(backend);
		String document = "<urn:source> <urn:next> \"<urn:s> <urn:p> <urn:o> .\" .";
		String[] bodies = {
				"?next parse:turtle (?s <urn:p> ?o) . SERVICE <urn:rdf4j:parse> { "
						+ CONFIG + "<urn:source> <urn:next> ?next }",
				"SERVICE <urn:rdf4j:parse> { [] parse:content ?next; parse:format \"text/turtle\" . "
						+ "?s <urn:p> ?o } ?doc parse:turtle (?source <urn:next> ?next)"
		};
		for (String body : bodies) {
			var rows = select("SELECT ?s ?o WHERE { " + body + " }", document);
			assertEquals(1, rows.size(), body);
			assertEquals(VF.createIRI("urn:s"), rows.get(0).getValue("s"));
			assertEquals(VF.createIRI("urn:o"), rows.get(0).getValue("o"));
		}
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void serviceDuplicateInputsStillAllocateFreshBlankNodes(Backend backend) {
		open(backend);
		var rows = select("SELECT ?s ?copy WHERE { VALUES ?copy { 1 1 } SERVICE <urn:rdf4j:parse> { "
				+ CONFIG + "?s <urn:p> ?o } }", "_:b <urn:p> <urn:o> .");
		assertEquals(2, rows.size());
		assertNotEquals(rows.get(0).getValue("s"), rows.get(1).getValue("s"));
		assertEquals(rows.get(0).getValue("copy"), rows.get(1).getValue("copy"));
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void tupleDeduplicationUsesTermEqualityRatherThanNumericEquality(Backend backend) {
		open(backend);
		var rows = select("SELECT ?o WHERE { ?doc parse:turtle (?s ?p ?o) }", "<urn:s> <urn:p> 1, 01, 1 .");
		assertEquals(2, rows.size());
		assertEquals(java.util.Set.of("1", "01"), rows.stream()
				.map(row -> row.getValue("o").stringValue())
				.collect(java.util.stream.Collectors.toSet()));
	}

	@ParameterizedTest
	@EnumSource(Backend.class)
	void ordinaryQueriesAreUnaffectedByTheRewriteFastPath(Backend backend) {
		open(backend);
		StringBuilder body = new StringBuilder("SELECT ?s WHERE { ");
		for (int i = 0; i < 32; i++) {
			connection.add(VF.createIRI("urn:s"), VF.createIRI("urn:p" + i), VF.createLiteral(i));
			body.append("?s <urn:p").append(i).append("> ?o").append(i).append(" . ");
		}
		body.append('}');
		var rows = select(body.toString(), null);
		assertEquals(1, rows.size());
		assertEquals(VF.createIRI("urn:s"), rows.get(0).getValue("s"));
	}
}
